require_once __DIR__.'/../shared/config.php'; require_admin(); $id=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT * FROM payments WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p||$p['status']!=='active'){flash('This payment cannot be changed.','error');header('Location: records.php');exit;}$services=db()->query('SELECT * FROM services WHERE active=1 ORDER BY service_item')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['cancel'])){$reason=trim($_POST['reason']??'');db()->prepare("UPDATE payments SET status='cancelled',cancelled_at=NOW(),cancelled_by=?,cancel_reason=? WHERE id=?")->execute([$_SESSION['user']['id'],$reason?:'No reason provided',$id]);db()->prepare('INSERT INTO payment_audit_logs(payment_id,action,details,performed_by,performed_by_name) VALUES(?,?,?,?,?)')->execute([$id,'cancelled',$reason,$_SESSION['user']['id'],$_SESSION['user']['full_name']]);flash('Payment cancelled.');header('Location: records.php');exit;}$name=trim($_POST['patient_name']);$phone=trim($_POST['patient_phone']);$sid=(int)$_POST['service_id'];$amount=(float)$_POST['amount'];$dt=$_POST['payment_datetime'];$sq=db()->prepare('SELECT service_item FROM services WHERE id=?');$sq->execute([$sid]);$service=$sq->fetchColumn();db()->prepare('UPDATE payments SET patient_name=?,patient_phone=?,service_id=?,service_name=?,amount=?,payment_datetime=? WHERE id=?')->execute([$name,$phone?:null,$sid,$service,$amount,date('Y-m-d H:i:s',strtotime($dt)),$id]);db()->prepare('INSERT INTO payment_audit_logs(payment_id,action,details,performed_by,performed_by_name) VALUES(?,?,?,?,?)')->execute([$id,'edited','Payment details updated.',$_SESSION['user']['id'],$_SESSION['user']['full_name']]);flash('Payment updated.');header('Location: receipt.php?id='.$id);exit;}
$page_title='Edit Payment';require __DIR__.'/header.php';?><div class="form-layout"><div><div class="intro"><span>ADMIN ONLY</span><h2>Edit or cancel payment</h2><p><?=e($p['payment_ref'])?></p></div><form class="panel form-panel" method="post"><input type="hidden" name="id" value="<?=$id?>"><div class="form-section"><label>Patient Name<input name="patient_name" value="<?=e($p['patient_name'])?>" required></label><label>Mobile Number<input name="patient_phone" value="<?=e($p['patient_phone'])?>"></label><label>Service<select name="service_id"><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$s['id']==$p['service_id']?'selected':''?>><?=e($s['service_item'])?></option><?php endforeach?></select></label><label>Amount<input type="number" step=".01" name="amount" value="<?=e($p['amount'])?>" required></label><label>Date & Time<input type="datetime-local" name="payment_datetime" value="<?=date('Y-m-d\TH:i',strtotime($p['payment_datetime']))?>" required></label></div><div class="form-actions"><a class="secondary" href="records.php">Cancel</a><button class="primary">Save Changes</button></div></form><form class="panel" method="post" style="margin-top:20px;padding:20px"><input type="hidden" name="id" value="<?=$id?>"><label>Reason for cancellation<input name="reason" required></label><button class="secondary" name="cancel" value="1" onclick="return confirm('Cancel this payment?')">Cancel This Payment</button></form></div></div><?php require __DIR__.'/footer.php';
